/**
 * Project-owned lint messages and the executors that enforce them.
 *
 * Executor kinds:
 * - eslint-core: a rule shipped with ESLint itself;
 * - eslint-plugin: a rule provided by an installed ESLint plugin;
 * - custom-eslint-rule: a project rule implemented in the referenced file.
 *
 * Messages generated by ESLint or a plugin without a project-owned message
 * are intentionally not copied here. Their executor remains the source of
 * truth for that text, while every project-owned message below identifies its
 * executor explicitly.
 */

function defineMessage({
  code,
  summary,
  reason,
  details = [],
  fix,
  executors,
}) {
  const lines = [code ? `${code}: ${summary}` : summary];
  if (reason) lines.push(`Reason: ${reason}`);
  lines.push(...details);
  if (fix) lines.push(`Fix: ${fix}`);

  return {
    code: code ?? null,
    message: lines.join("\n"),
    executors,
  };
}

